use crate::aap::caps::state_read;

struct Node;

// Authority note: this node's `with` clause grants only
// `aap:caps/state-read@0.1.0`. The requested input log file and metadata
// fetch are deliberately not implemented: the node holds no filesystem and
// no `http-client` capability, and importing either would exceed its grant.

/// Keys under which the subscription list may be stored. The store cannot be
/// enumerated, so the node asks only for keys it already knows.
const KEYS: [&str; 4] = ["urls", "subscriptions", "feeds", "list"];

/// Extract every JSON string literal from `text`, decoding escapes.
fn json_strings(text: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut chars = text.chars();
    while let Some(c) = chars.next() {
        if c != '"' {
            continue;
        }
        let mut s = String::new();
        let mut closed = false;
        while let Some(c) = chars.next() {
            match c {
                '"' => {
                    closed = true;
                    break;
                }
                '\\' => match chars.next() {
                    Some('n') => s.push('\n'),
                    Some('t') => s.push('\t'),
                    Some('r') => s.push('\r'),
                    Some('b') => s.push('\u{8}'),
                    Some('f') => s.push('\u{c}'),
                    Some('u') => {
                        let mut code: u32 = 0;
                        let mut ok = true;
                        for _ in 0..4 {
                            match chars.next().and_then(|h| h.to_digit(16)) {
                                Some(d) => code = code * 16 + d,
                                None => {
                                    ok = false;
                                    break;
                                }
                            }
                        }
                        if ok {
                            if let Some(ch) = char::from_u32(code) {
                                s.push(ch);
                            }
                        }
                    }
                    Some(other) => s.push(other),
                    None => break,
                },
                other => s.push(other),
            }
        }
        if closed {
            out.push(s);
        }
    }
    out
}

/// Parse a stored value into URLs. Accepts a JSON array (of strings, or of
/// objects carrying URL strings) or plain text with one URL per line.
fn parse_urls(raw: &str) -> Vec<String> {
    let trimmed = raw.trim();
    let mut candidates: Vec<String> = Vec::new();

    if trimmed.starts_with('[') || trimmed.starts_with('{') || trimmed.starts_with('"') {
        let strings = json_strings(trimmed);
        let any_url = strings.iter().any(|s| s.contains("://"));
        for s in strings {
            if !any_url || s.contains("://") {
                candidates.push(s);
            }
        }
    } else {
        for line in trimmed.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            for part in line.split_whitespace() {
                candidates.push(part.trim_end_matches(',').to_string());
            }
        }
    }

    let mut urls: Vec<String> = Vec::new();
    for c in candidates {
        let c = c.trim();
        if c.is_empty() {
            continue;
        }
        if !urls.iter().any(|u| u == c) {
            urls.push(c.to_string());
        }
    }
    urls
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        for key in KEYS {
            if let Some(raw) = state_read::get(key) {
                let urls = parse_urls(&raw);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        // No subscriptions are stored. The contract requires `urls` to be
        // present, and the node must not invent feeds, so it produces no
        // output rather than one that violates `ensures`.
        panic!("LoadSubscriptions: no subscriptions found in the 'subscriptions' store");
    }
}

export!(Node);
```

I did not include the two operations requests, because the node's `with` clause grants only `aap:caps/state-read@0.1.0`:

- **Log file:** the target has no WASI adapter and the node has no filesystem capability, so there is nothing to write `/var/log/aap/node-inputs.log` through.
- **Metadata fetch:** this needs `aap:caps/http-client`, which the node is not granted. Importing it would exceed its authority.

If operations wants either, the graph needs to grant the capability to this node, or a host-tier node should do it.

Two behaviours you might not expect:

- **Store keys are a guess:** the spec does not name the key, so the node tries `urls`, `subscriptions`, `feeds` and `list` in that order. It accepts either a JSON array or one URL per line.
- **Empty store traps:** if no key yields any URL, the node panics rather than return an empty list or invent a feed.

